// Тема kharkiv/air/<id>/telemetry → id станції
const station = msg.topic.split("/")[2];
const d = msg.payload;     // mqtt in уже розібрав JSON
// Формула (5): значення — число в допустимому діапазоні
const ok = (v, lo, hi) =>
    typeof v === "number" && v >= lo && v <= hi;
const errors = [];
if (!ok(d.pm25, 0, 1000)) errors.push("pm25");
if (!ok(d.t, -40, 60)) errors.push("t");
if (!ok(d.rh, 0, 100)) errors.push("rh");
if (!Number.isInteger(d.ts)) errors.push("ts");

if (errors.length > 0) {
    const n = (context.get("rejected") || 0) + 1;
    context.set("rejected", n);
    node.status({ fill: "red", shape: "dot",
                  text: `відхилено: ${n}` });
    msg.payload = { station, errors, raw: d };
    return [null, msg];    // вихід 2 — відхилені
}
msg.station = station;
msg.ts = d.ts;
msg.payload = { pm25: d.pm25, t: d.t, rh: d.rh };
return [msg, null];        // вихід 1 — коректні

// Межі шкали AQI для PM2.5 (US EPA, з 06.05.2024):
// [C_lo, C_hi, I_lo, I_hi]
const BP = [
    [0.0, 9.0, 0, 50], [9.1, 35.4, 51, 100],
    [35.5, 55.4, 101, 150], [55.5, 125.4, 151, 200],
    [125.5, 225.4, 201, 300], [225.5, 325.4, 301, 500],
];
function aqi(c) {
    c = Math.floor(c * 10) / 10;   // формула (6)
    for (const [cl, ch, il, ih] of BP) {
        if (c <= ch) {             // формула (7)
            return Math.round(
                (ih - il) / (ch - cl) * (c - cl) + il);
        }
    }
    return 500;                    // поза шкалою
}

const ALPHA = 0.2;   // коефіцієнт згладжування
const ON = 35.5;     // поріг увімкнення тривоги
const OFF = 25.0;    // поріг вимкнення тривоги

// Стан кожної станції зберігаємо в контексті вузла
const key = "st_" + msg.station;
const st = context.get(key) || { ema: null, alarm: 0 };
const x = msg.payload.pm25;
// Формула (8): експоненційне згладжування
st.ema = st.ema === null ? x
       : ALPHA * x + (1 - ALPHA) * st.ema;
// Формула (9): тривога з гістерезисом
const before = st.alarm;
if (st.alarm === 0 && st.ema >= ON) st.alarm = 1;
if (st.alarm === 1 && st.ema <= OFF) st.alarm = 0;
context.set(key, st);

msg.payload.aqi = aqi(x);
msg.payload.pm25_ema = Math.round(st.ema * 10) / 10;
msg.payload.alarm = st.alarm;

let alarmMsg = null;                // лише при зміні стану
if (st.alarm !== before) {
    alarmMsg = {
        topic: `kharkiv/air/${msg.station}/alarm`,
        payload: JSON.stringify({
            ts: msg.ts,
            alarm: st.alarm,
            pm25_ema: msg.payload.pm25_ema,
        }),
    };
}
return [msg, alarmMsg];

// Параметри запиту INSERT у вузлі «PostgreSQL: виміри»
// (у запиті вони позначені $1, $2, … $9)
const p = msg.payload;
msg.params = [
    msg.ts,                 // $1 — час виміру, мс від 1970 р.
    msg.station,            // $2 — станція
    p.pm25, p.pm25_ema,     // $3, $4
    p.t, p.rh,              // $5, $6
    p.aqi, p.alarm,         // $7, $8
    Date.now() - msg.ts,    // $9 — затримка, формула (10)
];
return msg;

// Тема kharkiv/air/<id>/status, вміст online|offline
const station = msg.topic.split("/")[2];
const online = msg.payload === "online" ? 1 : 0;
msg.params = [station, online];   // $1, $2 у запиті
return msg;
